            "swapping_pxa_to_pxs_is_instant_the": "PXA를 PXS로 전환하면 즉시 처리됩니다. PXA의 절반이 바로 전환되며 5% 수수료가 차감되고, 나머지 절반은 담보로 잠겼다가 약 3.5일 후 그때의 가격에 맞춰 조정되어 반환됩니다. PXS를 PXA로 전환할 때는 수수료가 없으며, 약 3.5일 후 그 시점의 witness 중앙값 가격으로 정산됩니다.",
            "pxp_usable_because": "{{text}}: 사용 가능 PXP <0>{{overall}}</0> (빌림 <1>{{borrowed}}</1> · 빌려줌 <2>{{lended}}</2> 반영)",
            "strong_strong_can_transfer_pixa_power_directly": "<strong>@{{username}}</strong> 계정은 일반적인 13주 파워 다운 주기를 거치지 않고 Pixa Power를 다른 계정으로 직접 전송할 수 있습니다. 이 금고는 다중 서명 계정이므로 단일 로그인만으로는 자금을 옮길 수 없습니다 — 아래 <strong>일괄 이체</strong>를 사용하세요. 각 키 보유자가 같은 묶음에 따로 서명한 뒤 병합해 브로드캐스트합니다.",
            "the_big_mac_index_is_a_renown": "빅맥 지수는 구매력, 물가 상승률, 소비자물가를 추적하는 잘 알려진 경제 지표입니다.",
            "beware_of_spam_and_phishing_links_in": "이체 메모에 포함된 스팸·피싱 링크에 주의하세요. 신뢰하지 않는 사용자의 링크는 열지 마세요. 개인 키를 제3자 사이트에 절대 입력하지 마세요. 거래는 블록체인에서 확인될 때까지 표시되지 않으며, 몇 분이 걸릴 수 있습니다.",
            "are_you_sure_you_want_to_power": "{{amount}} PXA를 파워 업할까요? 유동 PXA가 스테이킹된 Pixa Power로 전환됩니다.",
            "are_you_sure_you_want_to_power_2": "{{amount}} PXP를 파워 다운할까요? 13회에 걸쳐 매주 지급됩니다.",
            "are_you_sure_you_want_to_swap": "{{amount}} PXA를 PXS로 전환할까요? 절반이 바로 전환되며 5% 수수료가 차감되고, PXS는 즉시 지급됩니다. 나머지 절반은 담보로 잠겼다가 약 3.5일 후 그 시점의 PXA 가격에 맞춰 조정되어 반환됩니다. 가격이 절반으로 떨어졌다면 아무것도 반환되지 않습니다. 전환은 되돌릴 수 없습니다.",
            "are_you_sure_you_want_to_swap_2": "{{amount}} PXS를 PXA로 전환할까요? PXS는 지금 잔액에서 빠져나가고, PXA는 약 3.5일 후 그 시점의 witness 중앙값 가격으로 도착합니다. 수수료는 없습니다. 전환은 되돌릴 수 없습니다.",
