            "where_the_supra_lands": "Supra가 내려앉는 곳",
            "when_a_supra_settles_the_body_is_delivered": "supra가 정산될 때, 몸은 실행 순간에 PXA로 전달됩니다. PXA는 의식이 내려앉아 쉬는 자리입니다.",
