            "protocol_emission_reaches_authors_curators_and_witnesses_as": "프로토콜 발행은 저자와 큐레이터, witness에게 PXA로 전해집니다 — 몸에 힘을 주는 일에 네트워크가 값을 치르는 것입니다.",
            "it_is_earned_through_protocol_emission_not": "이것은 프로토콜 발행으로 얻는 것이며, 어떤 회사가 발행하거나 판매하지 않습니다. 보유는 지분도, 예치금도, 수익의 약속도 아니며, 어떤 주체의 수익이나 자산에 대한 권리도 주지 않습니다. 결제용 토큰으로 광고되지도 않습니다. PXA는 PXP의 유동 상태일 뿐이므로, PXP에 적용되는 것과 같은 FINMA의 유틸리티 토큰 판단(Nutzungs-Token, 2025년 3월 27일, ref. G01518211)이 그대로 적용됩니다 — 전체 기록은 PXP 시트를 보십시오.",
