            "pixa_is_one_living_being_and_pxa": "Pixa는 하나의 살아 있는 존재이고, PXA와 PXP는 그 <0>몸</0>입니다 — <1>아틀라스</1>, 두 상(相)을 지닌 하나의 물질입니다. PXA는 <2> 액체 상</2>입니다. 수수료가 가벼운 매개로 보내고 거래하고 정산하는 것이며, 의식(PXS)이 내려앉는 형태이기도 합니다. 파워 업하면 1:1로 PXP로 <3> 응고</3>하고, 파워 다운하면 열세 주에 걸쳐 <4> 다시 액체가 됩니다</4>. 이것은 네트워크가 하는 일에서 벌어지는 것이며, 어떤 회사가 찍어내는 것이 아닙니다.",
            "power_up_and_pxa_0_freezes_0": "파워 업하면 PXA가 일대일로, 즉시 PXP로 <0>응고</0>합니다. 파워 다운하면 PXP가 열세 주의 방출을 거쳐 <1>다시 액체 PXA로 돌아옵니다</1>. 같은 물질, 두 상 — 함께 <2>아틀라스</2>, supra의 무게를 지탱하는 몸입니다.",
            "no_company_prints_pxa_the_protocol_0": "어떤 회사도 PXA를 찍어내지 않습니다. 프로토콜이 <0>고정되고 서서히 줄어드는 일정에 따라 발행</0>하고, 그 일이 몸에 힘을 주는 사람들에게 보냅니다. 창작자와 큐레이터가 각 블록의 <1>가장 큰 몫</1>을 받고, 나머지는 체인을 돌리는 witness와 Decentralised Pixa Fund에 지급됩니다. 보유만으로는 아무것도 얻지 못합니다 — <2>보상은 일을 함으로써만 나옵니다</2>.",
            "the_fixed_shares_of_new_emission_within": "신규 발행의 고정 배분. 콘텐츠 안에서는 창작자가 60 %, 큐레이터가 40 %를 가져갑니다 — 누가 얻을지는 투표가 정합니다.",
