            "pixa_is_one_living_being_and_pxa": "Pixa는 하나의 살아 있는 존재이고, PXA와 PXP는 그 <0>몸</0>입니다 — <1>아틀라스</1>, 두 상을 지닌 하나의 물질입니다. PXP는 <2> 고체 상</2>입니다. 1:1로 응고한 PXA로, 존재에 <3> 무게</3>(거버넌스)와 수수료 없는 대역을 줍니다. 또한 <4>정신</4>의 방향을 잡는 바닥짐이기도 합니다 — witness는 스테이킹된 PXP로 선출되므로, 정신은 몸이 스스로에 대해 만들어내는 것입니다. 원할 때 언제든 다시 액체 PXA로 녹이십시오. 어떤 당사자도 바꿀 수 없는 열세 주의 방출을 통해서입니다.",
