            "each_week_another_equal_slice_melts_back": "매주 또 하나의 같은 몫이 액체 PXA로 녹아 돌아오므로, 잔액은 100 %를 향해 꾸준하고 예측 가능한 오름세로 사용 가능해집니다. 일정을 보여주는 예시이며 실시간 데이터가 아닙니다.",
