            "held_back_by_haircut": "헤어컷으로 유보됨",
            "when_you_settle_the_body_is_delivered": "정산할 때 몸은 실행 순간에 PXA로 전달됩니다 — 오라클이 함의한 무게에 헤어컷을 곱한 금액입니다. 그래서 '기초자산'은 틀린 말입니다. 기초자산이라는 말은 사물과 그에 대한 파생이라는 두 개의 별도 자산을 전제하기 때문입니다. 그러나 supra와 atlas는 두 개가 아닙니다. 하나의 몸이 두 개의 층위에서 보이는 것입니다 — 몸은 있는 그대로이고, supra는 그 몸이 투영해야 한다고 정신이 말하는 바입니다. 의식은 몸이 소유하는 무엇이 아닙니다. 그것은 깨어 있는 몸입니다.",
            "no_monetary_mechanism_removes_risk_a_stablecoin_concentrates": "위험을 없애는 화폐 장치는 없습니다. 법정화폐 준비금형 코인은 위험을 그 준비금의 건전성과 발행자의 지급 능력에 몰아넣습니다. supra는 그 위험을 창작 경제의 변동성 — 아틀라스의 분산 — 과 합의의 건전성 — witness 나침반의 견실함 — 으로 옮기고, 방어된 숫자 뒤에 감추는 대신 초과담보와 아무것도 방어하지 않는 헤어컷으로 드러내 놓고 다룹니다.",
            "body_at_the_weight": "{{label}}에서의 몸 무게",
            "pixa_supra_pxs": "Pixa Supra · PXS",
            "a_coin_with_its_own_body_mind": "자신의 몸과 정신, 영혼을 지닌 코인",
