            "floor_30_spent": "하한 · 약 30% 소모",
            "design_target": "설계 목표",
            "deep_capacity_10_spent": "심층 여력 · 약 10% 소모",
            "design_target_2": "설계 목표",
            "the_consciousness_supra": "의식 · Supra",
            "hold_pxs_and_you_hold_the_projection": "PXS를 보유한다는 것은 몸 자체가 아니라 그 투영을 보유하는 것입니다.",
            "the_soul_macro": "영혼 · Macro",
            "pixa_never_defends_pixa_adjusts": "Pixa는 결코 방어하지 않습니다. Pixa는 조정합니다.",
            "beside_fiat_never_within_it": "법정화폐 곁에, 결코 그 안에는 아닙니다",
