            "adding_a_password_provides_extra_security_especi": "비밀번호를 추가하면 특히 짧은 시드 구문에서 보안이 강화됩니다.",
            "you_are_about_to_request_a_change": "<0>@{{username}}</0> 님의 복구 계정 변경을 요청하려 합니다.",
            "nominate_a_trusted_account_a_co_founder": "신뢰할 수 있는 계정 — 공동 창업자, 본인이 관리하는 다른 지갑, 또는 다른 경로로 연락할 수 있는 지인 — 을 지정해 두면, owner 키를 잃어버리거나 유출되었을 때 접근 권한을 되찾는 데 도움을 받을 수 있습니다. 복구 절차는 owner 키의 이력을 사용하므로, 복구 계정만으로는 결코 당신의 계정을 빼앗을 수 없습니다. 오직 복구를 도울 수 있을 뿐입니다. 변경은 30일의 대기 기간이 지난 뒤에 적용됩니다.",
            "strong_30_day_waiting_period_strong_changing": "<strong>30일 대기 기간.</strong> 복구 계정 변경은 즉시 적용되지 않습니다. 새 요청은 <strong>브로드캐스트 후 30일이 지나야</strong> 적용되며, 그때까지는 현재 복구 계정이 유효합니다. 대기 기간 중 다시 브로드캐스트하면 대기 중인 요청이 대체됩니다. 현재 값으로 되돌리면 대기 중인 변경이 취소됩니다.",
            "pick_someone_you_trust_personally_a_co": "개인적으로 신뢰하는 상대를 고르세요. 공동 창업자, 본인이 관리하는 다른 계정, 또는 소유자와 다른 경로로 연락할 수 있는 지갑 등입니다.",
            "generate_a_fresh_seed_phrase_to_derive": "계정의 새 키를 도출할 새 시드 구문을 생성합니다. 시드 구문은 모든 계정 키의 마스터 키입니다 — 안전하게 보관하고 절대 공유하지 마세요. 아래에서 확인하면 owner 키로 키 갱신 트랜잭션에 서명합니다.",
            "this_will_strong_cancel_any_pending_recovery": "현재 복구 계정과 동일한 값을 다시 브로드캐스트해 <strong>대기 중인 복구 계정 변경을 모두 취소</strong>합니다. 30일 요청은 대체되며, 그동안 현재 복구 계정이 계속 유효합니다.",
            "once_broadcast_the_chain_will_create_a": "브로드캐스트하면 체인이 <strong>30일 후</strong> 적용되는 대기 요청을 생성합니다. 그때까지는 현재 복구 계정(<0>@{{currentRecovery}}</0>)이 유효합니다. <strong>owner 키</strong>를 입력하라는 요청을 받게 됩니다.",
            "posting_description_1": "이 키는 게시, 댓글, 투표 같은 소셜 활동에 사용합니다. 권한이 제한되어 있어 금전 관련 작업에는 사용할 수 없습니다.",
            "posting_description_2": "이 키는 Pixagram.com 같은 Pixa 기반 소셜 네트워크 로그인에 사용하세요. 안전하게 보관하세요.",
            "active_description_1": "이 키는 토큰 이체와 교환 같은 더 민감한 금전 관련 작업을 위한 추가 권한을 갖고 있습니다.",
            "active_description_2": "지갑 관련 작업을 수행할 때 Active 키로 인증하라는 요청을 받을 수 있습니다. Active Key는 신뢰하는 앱에만 입력하세요. 이 키에 접근할 수 있는 사람은 누구나 회원님의 토큰을 가져갈 수 있습니다.",
            "owner_description_1": "Owner 키는 다른 키를 변경하는 데 필요합니다. 계정을 복구하거나 다른 키를 변경할 수 있는 추가 권한을 갖습니다. 가장 중요한 키이므로 오프라인에 안전하게 보관해야 합니다.",
            "memo_description_1": "Memo 키는 조금 특별합니다. Memo Key가 할 수 있는 일은 블록체인을 통해 전송되는 비공개 메시지를 암호화하고 복호화하는 것뿐입니다.",
