            "the_price_feed_for_the_pixasupra_versus": "PixaSupra 대 Pixa의 가격 피드는 약 1:57입니다. 가격 피드는 통화 간 인센티브를 맞추는 데 쓰입니다. PixaSupra와 Pixa는 오라클을 참조하는 토큰보다 유동 토큰이 <b>3.3배 많은</b> 상태를 균형점으로 삼으며, 이로써 PixaSupra는 Pixa 시가총액의 30% 미만으로 유지됩니다. 즉 현재 공급을 조정할 여유가 <b>3.7배</b> 있으며, Pixa 가격이 그만큼 떨어지면 haircut 규칙이 적용됩니다.",
