            "similar_to_most_stablecoin_its_algorithms_requir": "궤도 수정은 운영자가 레버에 손을 얹는 일이 아닙니다. 가격 피드와 프로토콜 파라미터는 witness의 합의로 정해지고, 공정한 APR이 시스템으로 하여금 그 피드를 따르게 하면서 장기 스테이킹에 보상합니다.",
            "the_blockchain_can_emit_various_ratio_of": "블록체인은 PixaSupra와 Pixa를 다양한 비율로 발행할 수 있습니다. PixaSupra는 오라클을 참조하는 환율에 따라 Pixa로 전환되므로, 발행된 PixaSupra는 Pixa 시가총액에 견주어 평가됩니다.",
