            "the_foundation_stewards_it_does_not_rule": " Foundation은 맡아 지킬 뿐, 다스리지 않는다. 여기서 지어지는 것은 그것을 짓는 모든 이의 것이다.",
            "should_governance_ever_fail_the_community_may": " 거버넌스가 언젠가 무너지더라도, 공동체는 이 일을 온전한 채로 다른 곳으로 옮겨 갈 수 있다.",
            "what_is_true_is_said_plainly_even": " 참된 것은, 편안한 허구가 더 쉬울 때에도, 있는 그대로 말해진다.",
            "we_endure_by_bending_to_the_storm": " 우리는 폭풍 앞에 몸을 굽혀 견디는 것이지, 폭풍이 오지 않는 척하여 견디는 것이 아니다.",
            "uniquely_we_are_free_together_we_are_stronger": "저마다 우리는 자유롭고, 함께하면 우리는 더 강하다.",
            "these_principles_are_the_foundation_of_pixa": "이 원칙들은 Pixa의 토대이자, 그 위에 우리가 세우는 공동체 — 정직하고, 공정하고, 오래 견디며, 하나로 뭉친 공동체 — 의 토대다. 프로토콜은 반드시 금해야 할 것만을 금한다. 그 선 너머의 모든 선한 것은 우리가 선택하는 품성이다. 이것이 그 품성이다. 우리가 창작에 임하는 정신, 서로를 대하는 방식, 그리고 스스로에게 지우는 기준. 이 원칙들은 누구도 힘으로 묶지 않지만, 그럼에도 우리 모두를 묶는다.",
