            "some_figures_could_not_be_valued_in": "일부 수치는 {{fiat}}(으)로 평가할 수 없었습니다: 가격 소스가 해당 항목의 {{fiat}} 환율을 반환하지 않았습니다. 이 항목은 0이 아니라 “{{na}}”(으)로 표시되며, 이를 포함하는 모든 합계는 불완전합니다. 이 보고서를 사용하기 전에 가격 소스를 수정하세요.",
