            "royalty_on_secondary_sales": "2차 판매 로열티",
            "the_author_shall_receive_a_royalty_of": "저작자는 마켓플레이스나 거래 수단과 관계없이 NFT의 모든 2차 판매 또는 이전에 대해 **{{royaltyPercentage}}%**의 로열티를 받습니다. 이 로열티는 지원되는 경우 스마트 계약 기능을 통해 자동으로 집행됩니다. 거래가 자동화된 시스템 밖에서 이루어지는 경우, 판매자는 저작자가 해당 로열티를 받도록 하고 앞서 언급한 권리가 준수되도록 할 책임이 있습니다.",
            "term_and_termination": "기간 및 종료",
            "when_the_nft_is_sold_or_otherwise": "NFT가 판매되거나 그 밖의 방법으로 이전되면, 본 라이선스가 보유자에게 부여하는 권리는 동시에 새 소유자에게 이전되며, 이전 보유자의 모든 권리는 별도의 통지 없이 종료됩니다. 소유 기간을 넘어서는 작품 사용은 무단 사용으로 간주됩니다.",
